package com.bank.ladder;

import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.List;
import java.util.Queue;
import java.util.Set;
import java.util.logging.Logger;

// Shortest one-letter-at-a-time migration between valid status codes (BFS).
public class StatusMigrationPlanner {

    private static final Logger log = Logger.getLogger(StatusMigrationPlanner.class.getName());

    public int shortestMigration(String begin, String end, List<String> validCodes) {
        Set<String> dict = new HashSet<>(validCodes);
        if (!dict.contains(end)) {
            log.info("End code not in valid list; migration impossible");
            return 0;
        }
        Set<String> visited = new HashSet<>();
        Queue<String> queue = new ArrayDeque<>();
        queue.add(begin);
        visited.add(begin);
        int level = 1;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String word = queue.poll();
                if (word.equals(end)) {
                    log.info("Migrated '" + begin + "' -> '" + end + "' in " + level + " steps");
                    return level;
                }
                char[] chars = word.toCharArray();
                for (int p = 0; p < chars.length; p++) {
                    char original = chars[p];
                    for (char ch = 'a'; ch <= 'z'; ch++) {
                        if (ch == original) continue;
                        chars[p] = ch;
                        String candidate = new String(chars);
                        if (dict.contains(candidate) && !visited.contains(candidate)) {
                            visited.add(candidate);
                            queue.add(candidate);
                        }
                    }
                    chars[p] = original; // restore for next position
                }
            }
            level++;
        }
        log.info("No valid migration path found");
        return 0;
    }
}
