package com.bank.ladder;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class MigrationDemo {

    private static final Logger log = Logger.getLogger(MigrationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Account Status Code Migration");
        List<String> validCodes = List.of("hot", "dot", "dog", "lot", "log", "cog");
        StatusMigrationPlanner planner = new StatusMigrationPlanner();
        planner.shortestMigration("hit", "cog", validCodes); // expect 5
    }
}
